import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import Header from '../../components/Header_c.jsx'; 
import "../../components/cliente.css"; 

const PaymentForm = () => {
  // Estado para manejar los datos del formulario (opcional, pero buena práctica)
  const [formData, setFormData] = useState({
    cardNumber: '',
    expiryDate: '',
    cvv: '',
    cardHolderName: '',
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prevState => ({
      ...prevState,
      [name]: value,
    }));
    // En un entorno real, aquí también podrías agregar lógica de validación
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    // En un entorno real, esta es la función donde integrarías la API
    // de un proveedor de pagos (Stripe, PayPal, etc.).
    console.log('Datos del formulario enviados:', formData);
    alert('Simulación de pago enviado. ¡Integración de API necesaria!');
  };

  return (
    <div className="payment-container">
      <h2>💳 Pasarela de Pago</h2>
      <form className="payment-form" onSubmit={handleSubmit}>

        <div className="form-group">
          <label htmlFor="cardNumber">Número de Tarjeta</label>
          <input
            type="text"
            id="cardNumber"
            name="cardNumber"
            value={formData.cardNumber}
            onChange={handleChange}
            placeholder="XXXX XXXX XXXX XXXX"
            maxLength="19" // 16 dígitos + 3 espacios
            required
          />
        </div>

        <div className="form-row">
          <div className="form-group half-width">
            <label htmlFor="expiryDate">Fecha de Vencimiento (MM/AA)</label>
            <input
              type="text"
              id="expiryDate"
              name="expiryDate"
              value={formData.expiryDate}
              onChange={handleChange}
              placeholder="MM/AA"
              maxLength="5"
              required
            />
          </div>

          <div className="form-group half-width">
            <label htmlFor="cvv">CVV</label>
            <input
              type="password"
              id="cvv"
              name="cvv"
              value={formData.cvv}
              onChange={handleChange}
              placeholder="123"
              maxLength="4"
              required
            />
          </div>
        </div>

        <div className="form-group">
          <label htmlFor="cardHolderName">Nombre del Titular</label>
          <input
            type="text"
            id="cardHolderName"
            name="cardHolderName"
            value={formData.cardHolderName}
            onChange={handleChange}
            placeholder="Nombre Apellido"
            required
          />
        </div>

        <button type="submit" className="pay-button">
          Pagar $99.99
        </button>

        <p className="security-note">
          🔒 Tu información está segura y encriptada.
        </p>
      </form>
    </div>
  );
};

export default PaymentForm;
